#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <limits>
using namespace std;
class Student{int roll;string name;double marks;public:Student():roll(0),name("Not set"),marks(0){}Student(int r,string n,double m):roll(r),name(n),marks(m){}~Student()=default;int getRoll()const{return roll;}string getName()const{return name;}double getMarks()const{return marks;}void setName(const string&n){name=n;}bool setMarks(double m){if(m<0||m>100)return false;marks=m;return true;}string grade()const{if(marks>=80)return "A";if(marks>=70)return "B";if(marks>=60)return "C";if(marks>=50)return "D";return "Needs improvement";}void display()const{cout<<"Roll: "<<roll<<" | Name: "<<name<<" | Marks: "<<marks<<" | Grade: "<<grade()<<"\n";}};
class StudentManager{vector<Student> students;void save(){ofstream f("students.txt");for(auto&s:students)f<<s.getRoll()<<"|"<<s.getName()<<"|"<<s.getMarks()<<"\n";}void load(){ifstream f("students.txt");string line;while(getline(f,line)){size_t a=line.find('|'),b=line.find('|',a+1);if(a==string::npos||b==string::npos)continue;try{students.emplace_back(stoi(line.substr(0,a)),line.substr(a+1,b-a-1),stod(line.substr(b+1)));}catch(...){}}}void add(){int r;double m;string n;cout<<"Roll number: ";cin>>r;cin.ignore(numeric_limits<streamsize>::max(),'\n');cout<<"Name: ";getline(cin,n);cout<<"Marks (0-100): ";cin>>m;for(auto&s:students)if(s.getRoll()==r){cout<<"Roll already exists.\n";return;}Student s(r,n,0);if(!s.setMarks(m)){cout<<"Marks must be between 0 and 100.\n";return;}students.push_back(s);save();cout<<"Student saved.\n";}void list(){if(students.empty())cout<<"No students found.\n";for(auto&s:students)s.display();}void search(){int r;cout<<"Roll number: ";cin>>r;for(auto&s:students)if(s.getRoll()==r){s.display();return;}cout<<"Student not found.\n";}public:StudentManager(){load();}void run(){int c;do{cout<<"\n=== Student Management ===\n1 Add student\n2 View students\n3 Search student\n0 Exit\nChoice: ";if(!(cin>>c)){cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');c=-1;}switch(c){case 1:add();break;case 2:list();break;case 3:search();break;case 0:save();break;default:cout<<"Choose a valid option.\n";}}while(c!=0);}};
int main(){StudentManager app;app.run();return 0;}